<style>
.date-picker{padding:13px;border:1px solid #d4cab8;border-radius:4px;background:#fffdf9}.date-picker-nav{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.date-picker-nav .btn{padding:6px 12px}.date-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px;text-align:center}.date-weekday{font:600 11px system-ui,sans-serif;color:#756a55;padding:5px 0}.date-day{min-height:38px;border:1px solid #e2d9c8;border-radius:3px;background:white;color:var(--ink);font:14px system-ui,sans-serif}.date-day.available{background:#f4eddd;border-color:#bb9653;color:#344c70;font-weight:700;cursor:pointer}.date-day.available:hover{background:#e9dcc0}.date-day.selected{background:#344c70;color:#fff;border-color:#344c70}.date-day:disabled{color:#bbb8af;background:#f3f0e9;border-color:transparent;text-decoration:line-through;cursor:not-allowed}.date-empty{min-height:38px}@media(max-width:420px){.date-picker{padding:9px}.date-grid{gap:3px}.date-day{min-height:34px}}
</style>
<script>
const dateInput=document.getElementById('date'),serviceSelect=document.getElementById('service'),timeSelect=document.getElementById('time'),slotNote=document.getElementById('slot-note'),outsideWrap=document.getElementById('outside-request'),outsideCheck=document.getElementById('outside-ceremony'),calendarGrid=document.getElementById('calendar-grid'),calendarNote=document.getElementById('calendar-note'),monthLabel=document.getElementById('month-label'),previousMonth=document.getElementById('previous-month'),nextMonth=document.getElementById('next-month');
const text={loading:@json(__('ui.loading_times')),selectDate:@json(__('ui.select_date_first')),noTimes:@json(__('ui.no_available_times')),chooseAnother:@json(__('ui.choose_another_date')),couldNotLoad:@json(__('ui.could_not_load_times')),refresh:@json(__('ui.refresh_try_again')),chooseFirst:@json(__('ui.choose_time_first')),chooseTime:@json(__('ui.choose_time')),noteRequired:@json(__('ui.note_required')),availableHint:@json(__('ui.available_dates_hint')),nextAvailable:@json(__('ui.next_available_date')),loadingDates:@json(__('ui.loading_dates')),noDates:@json(__('ui.no_available_dates_month')),couldNotLoadDates:@json(__('ui.could_not_load_dates'))};
const availabilityUrl=@json(route('priests.availability',$priest->slug)),availableDatesUrl=@json(route('priests.available-dates',$priest->slug)),locale=@json(app()->getLocale()),todayString=@json(now()->toDateString());
const today=new Date(todayString+'T00:00:00'),calendarMonth=new Date(today.getFullYear(),today.getMonth(),1);let availableDateSet=new Set(),dateRequestId=0;
function monthKey(date){return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')}
function renderCalendar(){const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),first=new Date(year,month,1),days=new Date(year,month+1,0).getDate();monthLabel.textContent=new Intl.DateTimeFormat(locale,{month:'long',year:'numeric'}).format(first);previousMonth.disabled=year===today.getFullYear()&&month===today.getMonth();calendarGrid.innerHTML='';for(let i=0;i<7;i++){const weekday=document.createElement('div');weekday.className='date-weekday';weekday.textContent=new Intl.DateTimeFormat(locale,{weekday:'short'}).format(new Date(2026,0,4+i));calendarGrid.appendChild(weekday)}for(let i=0;i<first.getDay();i++){const blank=document.createElement('span');blank.className='date-empty';calendarGrid.appendChild(blank)}for(let day=1;day<=days;day++){const value=year+'-'+String(month+1).padStart(2,'0')+'-'+String(day).padStart(2,'0'),date=new Date(year,month,day),button=document.createElement('button');button.type='button';button.className='date-day';button.textContent=String(day);button.disabled=!availableDateSet.has(value)||date<today;if(availableDateSet.has(value)&&date>=today)button.classList.add('available');if(dateInput.value===value)button.classList.add('selected');button.setAttribute('aria-label',new Intl.DateTimeFormat(locale,{dateStyle:'full'}).format(date));button.setAttribute('aria-pressed',String(dateInput.value===value));button.addEventListener('click',()=>selectDate(value));calendarGrid.appendChild(button)}previousMonth.disabled=year===today.getFullYear()&&month===today.getMonth();nextMonth.disabled=false}
async function loadAvailableDates(){const requestId=++dateRequestId;availableDateSet=new Set();renderCalendar();calendarNote.textContent=text.loadingDates;try{const url=new URL(availableDatesUrl,location.origin);url.searchParams.set('month',monthKey(calendarMonth));url.searchParams.set('service_type',serviceSelect.value);const response=await fetch(url);if(!response.ok)throw new Error('Could not load dates');const data=await response.json();if(requestId!==dateRequestId)return;availableDateSet=new Set(data.dates);renderCalendar();calendarNote.textContent=data.dates.length?text.availableHint:text.noDates;if(dateInput.value&&!availableDateSet.has(dateInput.value)){dateInput.value='';timeSelect.disabled=true;timeSelect.innerHTML='';timeSelect.add(new Option(text.selectDate,''));syncBooking()}}catch(error){if(requestId===dateRequestId)calendarNote.textContent=text.couldNotLoadDates}}
async function findNextAvailableDate(){const requestId=++dateRequestId;dateInput.value='';availableDateSet=new Set();calendarMonth.setFullYear(today.getFullYear(),today.getMonth(),1);renderCalendar();calendarNote.textContent=text.loadingDates;timeSelect.disabled=true;timeSelect.innerHTML='';timeSelect.add(new Option(text.selectDate,''));slotNote.textContent='';for(let offset=0;offset<24;offset++){if(requestId!==dateRequestId)return;const month=new Date(today.getFullYear(),today.getMonth()+offset,1);try{const url=new URL(availableDatesUrl,location.origin);url.searchParams.set('month',monthKey(month));url.searchParams.set('service_type',serviceSelect.value);const response=await fetch(url);if(!response.ok)throw new Error('Could not load dates');const data=await response.json();if(requestId!==dateRequestId)return;const nextDate=data.dates.filter(value=>value>=todayString).sort()[0];if(nextDate){calendarMonth.setFullYear(month.getFullYear(),month.getMonth(),1);availableDateSet=new Set(data.dates);dateInput.value=nextDate;renderCalendar();const formatted=new Intl.DateTimeFormat(locale,{dateStyle:'full'}).format(new Date(nextDate+'T00:00:00'));calendarNote.textContent=text.nextAvailable.replace(':date',formatted);await loadSlots();syncBooking();return}}catch(error){if(requestId===dateRequestId){calendarNote.textContent=text.couldNotLoadDates;return}}}if(requestId===dateRequestId)calendarNote.textContent=text.noDates}
async function selectDate(value){dateInput.value=value;renderCalendar();await loadSlots();syncBooking();clearBookingError()}
previousMonth.addEventListener('click',()=>{if(previousMonth.disabled)return;calendarMonth.setMonth(calendarMonth.getMonth()-1);loadAvailableDates()});nextMonth.addEventListener('click',()=>{calendarMonth.setMonth(calendarMonth.getMonth()+1);loadAvailableDates()});
async function loadSlots(){timeSelect.disabled=true;timeSelect.innerHTML='';timeSelect.add(new Option(text.loading,''));if(!dateInput.value){timeSelect.innerHTML='';timeSelect.add(new Option(text.selectDate,''));return}try{const url=new URL(availabilityUrl,location.origin);url.searchParams.set('date',dateInput.value);url.searchParams.set('service_type',serviceSelect.value);const response=await fetch(url);if(!response.ok)throw new Error('Could not load times');const data=await response.json();timeSelect.innerHTML='';if(!data.slots.length){timeSelect.add(new Option(text.noTimes,''));slotNote.textContent=text.chooseAnother;return}slotNote.textContent='';timeSelect.add(new Option(text.chooseTime,''));data.slots.forEach(slot=>timeSelect.add(new Option(slot,slot)));timeSelect.disabled=false}catch(error){timeSelect.innerHTML='';timeSelect.add(new Option(text.couldNotLoad,''));slotNote.textContent=text.refresh}}
function updateOutsideRequest(){const isConfession=serviceSelect.value==='confession';if(!isConfession)outsideCheck.checked=false;outsideWrap.hidden=!isConfession;const message=document.getElementById('message')||document.getElementById('guest-message');if(message)message.required=isConfession&&outsideCheck.checked;const outsideField=document.getElementById('booking-outside');if(outsideField)outsideField.value=outsideCheck.checked?'1':'0'}
serviceSelect.addEventListener('change',()=>{dateInput.value='';timeSelect.disabled=true;timeSelect.innerHTML='';timeSelect.add(new Option(text.selectDate,''));slotNote.textContent='';updateOutsideRequest();findNextAvailableDate()});outsideCheck.addEventListener('change',updateOutsideRequest);
const query=new URLSearchParams(location.search);if(query.has('service_type')&&[...serviceSelect.options].some(option=>option.value===query.get('service_type')))serviceSelect.value=query.get('service_type');if(query.has('outside_ceremony'))outsideCheck.checked=query.get('outside_ceremony')==='1';updateOutsideRequest();if(query.has('date')){const requestedDate=query.get('date'),date=new Date(requestedDate+'T00:00:00');calendarMonth.setFullYear(date.getFullYear(),date.getMonth(),1)}
function syncBooking(){const startField=document.getElementById('starts_at');if(startField){startField.value=dateInput.value&&timeSelect.value?dateInput.value+' '+timeSelect.value:'';startField.dispatchEvent(new Event('input',{bubbles:true}))}const serviceField=document.getElementById('booking-service');if(serviceField)serviceField.value=serviceSelect.value;updateOutsideRequest()}
function clearBookingError(){const error=document.getElementById('booking-error');if(error)error.textContent=''}
function showBookingError(message){const error=document.getElementById('booking-error');if(error)error.textContent=message;document.getElementById('time')?.focus()}
timeSelect.addEventListener('change',()=>{syncBooking();clearBookingError()});
document.getElementById('booking')?.addEventListener('beforecustomvalidation',syncBooking);
document.getElementById('sign-in-to-book')?.addEventListener('click',()=>{if(!dateInput.value||!timeSelect.value){showBookingError(text.chooseFirst);return}const guestMessage=document.getElementById('guest-message'),guestNote=guestMessage?.value||'';if(outsideCheck.checked&&!guestNote.trim()){showBookingError(text.noteRequired);guestMessage?.focus();return}clearBookingError();const returnUrl=new URL(location.pathname,location.origin);returnUrl.searchParams.set('date',dateInput.value);returnUrl.searchParams.set('service_type',serviceSelect.value);returnUrl.searchParams.set('time',timeSelect.value);if(outsideCheck.checked)returnUrl.searchParams.set('outside_ceremony','1');sessionStorage.setItem('priestagenda_booking_note',guestNote);const loginUrl=new URL(@json(route('login')),location.origin);loginUrl.searchParams.set('return_to',returnUrl.pathname+returnUrl.search);location.href=loginUrl.toString()});
(query.has('date')?loadAvailableDates():findNextAvailableDate()).then(async()=>{const note=document.getElementById('message'),savedNote=sessionStorage.getItem('priestagenda_booking_note');if(note&&savedNote!==null){note.value=savedNote;sessionStorage.removeItem('priestagenda_booking_note')}if(query.has('date')){if(availableDateSet.has(query.get('date'))){await selectDate(query.get('date'));if(query.has('time')){timeSelect.value=query.get('time');syncBooking()}}else await findNextAvailableDate()}});
</script>
@endpush
